172			titleTimer = setInterval(() => {
173				const frame = TITLE_FRAMES[titleFrame % TITLE_FRAMES.length];
174				ctx.ui.setTitle(`${frame} ${forgeTitle(pi, ctx)}`);
175				titleFrame++;
176			}, 300);
177		}
178	
179		function applyOn(ctx: ExtensionContext): void {
180			enabled = true;
181			lastContext = ctx;
182			if (!ctx.hasUI) return;
183	
184			if (supports(ctx.ui, "setHeader")) {
185				ctx.ui.setHeader((_tui, theme) => ({
186					render: () => forgeHeader(ctx, theme),
187					invalidate() {},
188				}));
189			}
190			if (supports(ctx.ui, "setWorkingIndicator")) {
191				ctx.ui.setWorkingIndicator(WORKING_INDICATOR);
192			}
193			if (supports(ctx.ui, "setHiddenThinkingLabel")) {
194				ctx.ui.setHiddenThinkingLabel(HIDDEN_THINKING_LABEL);
