202			enabled = false;
203			const activeCtx = ctx || lastContext;
204			stopTitleSpinner(activeCtx, activeCtx ? vanillaTitle(pi, activeCtx) : undefined);
205			if (!activeCtx?.hasUI) return;
206	
207			if (supports(activeCtx.ui, "setHeader")) {
208				activeCtx.ui.setHeader(undefined);
209			}
210			if (supports(activeCtx.ui, "setWorkingIndicator")) {
211				activeCtx.ui.setWorkingIndicator(undefined);
212			}
213			if (supports(activeCtx.ui, "setHiddenThinkingLabel")) {
214				activeCtx.ui.setHiddenThinkingLabel();
215			}
216			if (supports(activeCtx.ui, "setTitle")) {
217				activeCtx.ui.setTitle(vanillaTitle(pi, activeCtx));
218			}
219		}
220	
221		pi.on("session_start", async (_event, ctx) => {
222			if (enabled) applyOn(ctx);
223		});
224	
225		pi.on("agent_start", async (_event, ctx) => {
226			startTitleSpinner(ctx);
227		});
228	
229		pi.on("agent_end", async (_event, ctx) => {
230			if (enabled) stopTitleSpinner(ctx, forgeTitle(pi, ctx));
231		});
232	
233		pi.on("session_shutdown", async (_event, ctx) => {
234			applyOff(ctx);
235		});
236	
237		pi.registerCommand("forge-atmosphere", {
238			description: "Show or toggle the visual Forge atmosphere [on|off].",
239			handler: async (args, ctx) => {
240				const arg = args.trim().toLowerCase();
241				if (arg === "on") {
242					applyOn(ctx);
243					if (ctx.hasUI) ctx.ui.notify("forge-atmosphere on", "info");
244					return;
245				}
246				if (arg === "off") {
247					applyOff(ctx);
248					if (ctx.hasUI) ctx.ui.notify("forge-atmosphere off", "info");
249					return;
250				}
251				if (!arg) {
252					if (ctx.hasUI) ctx.ui.notify(`forge-atmosphere: ${enabled ? "on" : "off"}`, "info");
253					return;
254				}
255				if (ctx.hasUI) ctx.ui.notify("usage: /forge-atmosphere [on|off]", "error");
256			},
257		});
258	}
