2282	
2283	### Autocomplete Providers
2284	
2285	Use `ctx.ui.addAutocompleteProvider()` to stack custom autocomplete logic on top of the built-in slash-command and path provider.
2286	
2287	Typical pattern:
2288	
2289	- inspect the text before the cursor
2290	- return your own suggestions when your extension-specific syntax matches
2291	- otherwise delegate to `current.getSuggestions(...)`
2292	- delegate `applyCompletion(...)` unless you need custom insertion behavior
2293	
2294	```typescript
2295	pi.on("session_start", (_event, ctx) => {
2296	  ctx.ui.addAutocompleteProvider((current) => ({
2297	    async getSuggestions(lines, cursorLine, cursorCol, options) {
2298	      const line = lines[cursorLine] ?? "";
2299	      const beforeCursor = line.slice(0, cursorCol);
2300	      const match = beforeCursor.match(/(?:^|[ \t])#([^\s#]*)$/);
2301	      if (!match) {
2302	        return current.getSuggestions(lines, cursorLine, cursorCol, options);
2303	      }
2304	
2305	      return {
2306	        prefix: `#${match[1] ?? ""}`,
2307	        items: [
2308	          { value: "#2983", label: "#2983", description: "Extension API for registering custom @ autocomplete providers" },
2309	          { value: "#2753", label: "#2753", description: "Reload stale resource settings" },
2310	        ],
2311	      };
2312	    },
2313	
2314	    applyCompletion(lines, cursorLine, cursorCol, item, prefix) {
2315	      return current.applyCompletion(lines, cursorLine, cursorCol, item, prefix);
2316	    },
2317	
2318	    shouldTriggerFileCompletion(lines, cursorLine, cursorCol) {
2319	      return current.shouldTriggerFileCompletion?.(lines, cursorLine, cursorCol) ?? true;
2320	    },
2321	  }));
2322	});
