2324	
2325	See [github-issue-autocomplete.ts](../examples/extensions/github-issue-autocomplete.ts) for a complete example that preloads the latest open GitHub issues with `gh issue list` and filters them locally for fast `#...` completion. It requires GitHub CLI (`gh`) and a GitHub repository checkout.
2326	
2327	### Custom Components
2328	
2329	For complex UI, use `ctx.ui.custom()`. This temporarily replaces the editor with your component until `done()` is called:
2330	
2331	```typescript
2332	import { Text, Component } from "@mariozechner/pi-tui";
2333	
2334	const result = await ctx.ui.custom<boolean>((tui, theme, keybindings, done) => {
2335	  const text = new Text("Press Enter to confirm, Escape to cancel", 1, 1);
2336	
2337	  text.onKey = (key) => {
2338	    if (key === "return") done(true);
2339	    if (key === "escape") done(false);
2340	    return true;
2341	  };
2342	
2343	  return text;
2344	});
2345	
2346	if (result) {
2347	  // User pressed Enter
2348	}
2349	```
2350	
2351	The callback receives:
2352	- `tui` - TUI instance (for screen dimensions, focus management)
2353	- `theme` - Current theme for styling
2354	- `keybindings` - App keybinding manager (for checking shortcuts)
2355	- `done(value)` - Call to close component and return value
2356	
2357	See [tui.md](tui.md) for the full component API.
2358	
2359	#### Overlay Mode (Experimental)
2360	
2361	Pass `{ overlay: true }` to render the component as a floating modal on top of existing content, without clearing the screen:
2362	
2363	```typescript
2364	const result = await ctx.ui.custom<string | null>(
2365	  (tui, theme, keybindings, done) => new MyOverlayComponent({ onClose: done }),
2366	  { overlay: true }
2367	);
2368	```
2369	
2370	For advanced positioning (anchors, margins, percentages, responsive visibility), pass `overlayOptions`. Use `onHandle` to control visibility programmatically:
2371	
2372	```typescript
2373	const result = await ctx.ui.custom<string | null>(
2374	  (tui, theme, keybindings, done) => new MyOverlayComponent({ onClose: done }),
2375	  {
2376	    overlay: true,
2377	    overlayOptions: { anchor: "top-right", width: "50%", margin: 2 },
2378	    onHandle: (handle) => { /* handle.setHidden(true/false) */ }
2379	  }
2380	);
2381	```
2382	
2383	See [tui.md](tui.md) for the full `OverlayOptions` API and [overlay-qa-tests.ts](../examples/extensions/overlay-qa-tests.ts) for examples.
2384	
2385	### Custom Editor
2386	
2387	Replace the main input editor with a custom implementation (vim mode, emacs mode, etc.):
2388	
2389	```typescript
2390	import { CustomEditor, type ExtensionAPI } from "@mariozechner/pi-coding-agent";
2391	import { matchesKey } from "@mariozechner/pi-tui";
2392	
2393	class VimEditor extends CustomEditor {
2394	  private mode: "normal" | "insert" = "insert";
2395	
2396	  handleInput(data: string): void {
2397	    if (matchesKey(data, "escape") && this.mode === "insert") {
2398	      this.mode = "normal";
2399	      return;
2400	    }
2401	    if (this.mode === "normal" && data === "i") {
2402	      this.mode = "insert";
2403	      return;
2404	    }
2405	    super.handleInput(data);  // App keybindings + text editing
2406	  }
2407	}
2408	
2409	export default function (pi: ExtensionAPI) {
2410	  pi.on("session_start", (_event, ctx) => {
2411	    ctx.ui.setEditorComponent((_tui, theme, keybindings) =>
2412	      new VimEditor(theme, keybindings)
2413	    );
2414	  });
2415	}
2416	```
2417	
2418	**Key points:**
2419	- Extend `CustomEditor` (not base `Editor`) to get app keybindings (escape to abort, ctrl+d, model switching)
2420	- Call `super.handleInput(data)` for keys you don't handle
2421	- Factory receives `theme` and `keybindings` from the app
2422	- Use `ctx.ui.getEditorComponent()` before `setEditorComponent()` to wrap the previously configured custom editor
2423	- Pass `undefined` to restore default: `ctx.ui.setEditorComponent(undefined)`
2424	
2425	To compose with another extension that already replaced the editor, capture the previous factory before setting yours:
2426	
2427	```typescript
2428	const previous = ctx.ui.getEditorComponent();
2429	ctx.ui.setEditorComponent((tui, theme, keybindings) =>
2430	  new MyEditor(tui, theme, keybindings, { base: previous?.(tui, theme, keybindings) })
2431	);
2432	```
2433	
2434	See [tui.md](tui.md) Pattern 7 for a complete example with mode indicator.
2435	
2436	### Message Rendering
2437	
2438	Register a custom renderer for messages with your `customType`:
2439	
2440	```typescript
2441	import { Text } from "@mariozechner/pi-tui";
2442	
2443	pi.registerMessageRenderer("my-extension", (message, options, theme) => {
2444	  const { expanded } = options;
2445	  let text = theme.fg("accent", `[${message.customType}] `);
2446	  text += message.content;
2447	
2448	  if (expanded && message.details) {
2449	    text += "\n" + theme.fg("dim", JSON.stringify(message.details, null, 2));
2450	  }
2451	
2452	  return new Text(text, 0, 0);
2453	});
2454	```
2455	
2456	Messages are sent via `pi.sendMessage()`:
2457	
2458	```typescript
2459	pi.sendMessage({
2460	  customType: "my-extension",  // Matches registerMessageRenderer
2461	  content: "Status update",
2462	  display: true,               // Show in TUI
2463	  details: { ... },            // Available in renderer
2464	});
2465	```
2466	
2467	### Theme Colors
2468	
2469	All render functions receive a `theme` object. See [themes.md](themes.md) for creating custom themes and the full color palette.
2470	
2471	```typescript
2472	// Foreground colors
2473	theme.fg("toolTitle", text)   // Tool names
2474	theme.fg("accent", text)      // Highlights
2475	theme.fg("success", text)     // Success (green)
2476	theme.fg("error", text)       // Errors (red)
2477	theme.fg("warning", text)     // Warnings (yellow)
2478	theme.fg("muted", text)       // Secondary text
2479	theme.fg("dim", text)         // Tertiary text
2480	
2481	// Text styles
2482	theme.bold(text)
2483	theme.italic(text)
2484	theme.strikethrough(text)
2485	```
2486	
2487	For syntax highlighting in custom tool renderers:
2488	
2489	```typescript
2490	import { highlightCode, getLanguageFromPath } from "@mariozechner/pi-coding-agent";
2491	
2492	// Highlight code with explicit language
2493	const highlighted = highlightCode("const x = 1;", "typescript", theme);
2494	
2495	// Auto-detect language from file path
2496	const lang = getLanguageFromPath("/path/to/file.rs");  // "rust"
2497	const highlighted = highlightCode(code, lang, theme);
2498	```
2499

