 * Now that we run the `pi-powerline-footer` package, footer ownership lives there.
 *
 * This file remains as a stats companion only: it keeps `/stats` for a detailed,
 * timed session breakdown without fighting the powerline package for footer control.
 */

import type { AssistantMessage } from "@mariozechner/pi-ai";
import type { ExtensionAPI, ExtensionContext } from "@mariozechner/pi-coding-agent";

function fmtNum(n: number): string {
	return n.toLocaleString("en-US");
}

function fmtCompact(n: number): string {
	if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
	if (n >= 100_000) return `${Math.round(n / 1_000)}k`;
	if (n >= 1_000) return `${(n / 1_000).toFixed(1)}k`;
	return String(n);
}

function shortModel(id: string): string {
	return id
		.replace(/-2025\d{4}/, "")
		.replace(/-2024\d{4}/, "");
}

/**
 * Cumulative API token stats across the entire session (including pre-compaction).
 * Uses getEntries() — not getBranch() — so compaction doesn't lose history.
 * This is for /stats detail view, NOT for the footer token count.
 */
function getCumulativeStats(ctx: ExtensionContext) {
	let input = 0;
	let output = 0;
	let cacheRead = 0;
	let cacheWrite = 0;
	let cost = 0;
	let turns = 0;
	for (const entry of ctx.sessionManager.getEntries()) {
		if (entry.type !== "message") continue;
		const msg = entry.message;
		if (msg.role === "user") turns++;
		if (msg.role === "assistant") {
			const m = msg as AssistantMessage;
			input += m.usage.input;
			output += m.usage.output;
			cacheRead += m.usage.cacheRead;
			cacheWrite += m.usage.cacheWrite;
			cost += m.usage.cost.total;
		}
	}
	return { input, output, cacheRead, cacheWrite, cost, total: input + output, turns };
}

