/** Smoke test: drive the real extension default export with a fake pi/ctx,
 * capture the header factory, and render every ignition frame. */
import forge from "./forge-atmosphere.ts";

const handlers: Record<string, (event: unknown, ctx: unknown) => Promise<void>> = {};
let headerFactory: ((tui: unknown, theme: unknown) => { render(w: number): string[]; dispose?(): void }) | undefined;
let workingIndicator: { frames?: string[]; intervalMs?: number } | undefined;
let workingMessages: string[] = [];

const theme = {
	fg: (_c: string, t: string) => t,
	bold: (t: string) => `\x1b[1m${t}\x1b[22m`,
};

const ui = {
	setHeader: (f: typeof headerFactory) => (headerFactory = f),
	setWorkingIndicator: (o: typeof workingIndicator) => (workingIndicator = o),
	setHiddenThinkingLabel: (_l?: string) => {},
	setTitle: (_t: string) => {},
	setWorkingMessage: (m?: string) => {
		if (m) workingMessages.push(m);
	},
	notify: (_m: string, _t?: string) => {},
};

const ctx = { hasUI: true, ui, cwd: "/home/[USER_372]", model: { id: "gpt-5.5" } };

const pi = {
	on: (ev: string, h: (event: unknown, ctx: unknown) => Promise<void>) => (handlers[ev] = h),
	registerCommand: (_n: string, _o: unknown) => {},
	getSessionName: () => null,
};

// biome-ignore lint: test harness intentionally passes structural fakes
forge(pi as never);

await handlers["session_start"]({}, ctx);
if (!headerFactory) throw new Error("header factory not set");

const tui = { requestRender: () => {} };
const component = headerFactory(tui, theme);

// Render at terminal width 80; strip nothing — print raw so colors show.
const IGNITION_STEPS = 7;
for (let i = 0; i < IGNITION_STEPS; i++) {
	// step is internal; rendering repeatedly after waiting lets the interval advance
	await new Promise((r) => setTimeout(r, 175));
	const lines = component.render(80);
	if (i === 0 || i === IGNITION_STEPS - 1) {
		console.log(`── frame after ${(i + 1) * 175}ms ──`);
		for (const line of lines) console.log(line);
		// verify no line exceeds width (strip ANSI before measuring)
		for (const line of lines) {
			const plain = line.replace(/\x1b\[[0-9;]*m/g, "");
			if (plain.length > 80) throw new Error(`line too wide: ${plain.length}`);
		}
	}
}
component.dispose?.();

// Working indicator sanity
if (!workingIndicator?.frames?.length) throw new Error("working indicator not set");
console.log(`indicator: ${workingIndicator.frames.length} frames @ ${workingIndicator.intervalMs}ms`);
console.log("frames:", workingIndicator.frames.join(" "));

// Forge stages advance per turn
await handlers["agent_start"]({}, ctx);
await handlers["agent_start"]({}, ctx);
await handlers["agent_start"]({}, ctx);
console.log("working messages:", workingMessages.join(" | "));

// Narrow terminal safety
const narrow = headerFactory(tui, theme).render(20);
for (const line of narrow) {
	const plain = line.replace(/\x1b\[[0-9;]*m/g, "");
	if (plain.length > 20) throw new Error(`narrow overflow: "${plain}" (${plain.length})`);
}
console.log("narrow width OK");
console.log("SMOKE OK");
process.exit(0);

